def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    p = [props.get(a.get('element')) or {} for a in sites]
    radii = [a.get('covalent_radius_A') or 0.0 for a in p]
    occ = [1.0 if a.get('occupancy') is None else max(0.0, a.get('occupancy')) for a in sites]
    coordination = [0.0 for a in sites]
    for edge in s.get('neighbors') or []:
        i = edge.get('i')
        j = edge.get('j')
        d = edge.get('distance_A') or 0.0
        if i is None or j is None or not 0 <= i < n or not 0 <= j < n or d <= 0:
            continue
        if radii[i] <= 0 or radii[j] <= 0:
            continue
        w = max(0.0, 1.35 - d / (radii[i] + radii[j])) / 0.35
        coordination[i] += occ[j] * w * w
    total = 0.0
    amount = 0.0
    for i in range(n):
        if occ[i] <= 0 or radii[i] <= 0:
            continue
        group = p[i].get('group')
        if p[i].get('Z') == 1:
            reference = 1.0
        elif group is not None and 13 <= group <= 17:
            reference = float(min(group - 10, 18 - group))
        else:
            continue
        excess = max(0.0, coordination[i] / reference - 1.0)
        total += occ[i] * excess * excess
        amount += occ[i]
    return float(total / amount) if amount > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    radii = [(props.get(a.get('element')) or {}).get('covalent_radius_A') or 0.0 for a in sites]
    occ = [1.0 if a.get('occupancy') is None else max(0.0, a.get('occupancy')) for a in sites]
    nearest = [None for a in sites]
    for edge in s.get('neighbors') or []:
        i = edge.get('i')
        j = edge.get('j')
        d = edge.get('distance_A') or 0.0
        if i is None or j is None or not 0 <= i < n or not 0 <= j < n or d <= 0:
            continue
        if radii[i] <= 0 or radii[j] <= 0 or occ[j] <= 0:
            continue
        ratio = d / (radii[i] + radii[j])
        if nearest[i] is None or ratio < nearest[i]:
            nearest[i] = ratio
    total = 0.0
    amount = 0.0
    for i in range(n):
        if occ[i] <= 0 or nearest[i] is None:
            continue
        total += occ[i] * max(0.0, nearest[i] - 1.0) ** 2
        amount += occ[i]
    return float(total / amount) if amount > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    radii = [(props.get(a.get('element')) or {}).get('covalent_radius_A') or 0.0 for a in sites]
    occ = [1.0 if a.get('occupancy') is None else max(0.0, a.get('occupancy')) for a in sites]
    amount = sum(occ)
    if amount <= 0:
        return 0.0
    adjacency = [[] for a in sites]
    for edge in s.get('neighbors') or []:
        i = edge.get('i')
        j = edge.get('j')
        d = edge.get('distance_A') or 0.0
        image = edge.get('image')
        if i is None or j is None or not 0 <= i < n or not 0 <= j < n or d <= 0:
            continue
        if radii[i] <= 0 or radii[j] <= 0 or occ[i] <= 0 or occ[j] <= 0:
            continue
        if image is None or len(image) != 3 or d >= 1.25 * (radii[i] + radii[j]):
            continue
        adjacency[i] = adjacency[i] + [(j, image)]
    offsets = [None for a in sites]
    total = 0.0
    for root in range(n):
        if offsets[root] is not None or occ[root] <= 0:
            continue
        offsets[root] = [0, 0, 0]
        frontier = [root]
        mass = occ[root]
        rank = 0
        first = [0, 0, 0]
        normal = [0, 0, 0]
        for step in range(n):
            if not frontier:
                break
            following = []
            for i in frontier:
                for j, image in adjacency[i]:
                    proposed = [offsets[i][k] + image[k] for k in range(3)]
                    if offsets[j] is None:
                        offsets[j] = proposed
                        following = following + [j]
                        mass += occ[j]
                        continue
                    cycle = [proposed[k] - offsets[j][k] for k in range(3)]
                    if not any(x != 0 for x in cycle):
                        continue
                    if rank == 0:
                        first = cycle
                        rank = 1
                    elif rank == 1:
                        cross = [first[1] * cycle[2] - first[2] * cycle[1], first[2] * cycle[0] - first[0] * cycle[2], first[0] * cycle[1] - first[1] * cycle[0]]
                        if any(x != 0 for x in cross):
                            normal = cross
                            rank = 2
                    elif rank == 2:
                        if sum(normal[k] * cycle[k] for k in range(3)) != 0:
                            rank = 3
            frontier = following
        total += mass * rank
    return float(total / amount)

def feature(s):
    if not s:
        return 0.0
    volume = s.get('volume_per_atom_A3')
    if volume is None or volume <= 0:
        volume = (s.get('basic_structure_statistics') or {}).get('volume_per_atom_A3')
    if volume is None or volume <= 0:
        return 0.0
    props = s.get('element_properties') or {}
    total = 0.0
    amount = 0.0
    for element, fraction in (s.get('composition') or {}).items():
        if fraction is None or fraction <= 0:
            continue
        radius = (props.get(element) or {}).get('covalent_radius_A')
        if radius is None or radius <= 0:
            continue
        total += fraction * radius ** 3
        amount += fraction
    return float(4.1887902047863905 * total / (amount * volume)) if amount > 0 else 0.0
